    return GetListResponse.fromJson(brevoRequireJsonObject(
        json ?? const <String, Object?>{},
        objectName: 'GetListResponse'));
  }

  /// `GET /contacts/lists`
  ///
  /// Get all the lists
  ///
  /// &lt;Note&gt;Ongoing changes for this endpoint.
  /// We're dropping support for the response attributes totalSubscribers and totalBlacklisted.
  /// These are non breaking changes. The default value for the attributes will be 0.&lt;/Note&gt;
  ///
  /// \[limit\]: Number of documents per page
  ///
  /// \[offset\]: Index of the first document of the page
  ///
  /// \[sort\]: Sort the results in the ascending/descending order of record creation. Default order is **descending** if `sort` is not passed
  Future<GetListsResponse> getLists(
      {int? limit,
      int? offset,
      GetListsRequestSort? sort,
      BrevoRequestOptions? options}) async {
    final json = await _client.requestJson(
        method: 'GET',
        path: '/contacts/lists',
        query: <String, Object?>{
          'limit': limit,
          'offset': offset,
          'sort': sort?.value
        },
        options: options);
    return GetListsResponse.fromJson(brevoRequireJsonObject(
        json ?? const <String, Object?>{},
        objectName: 'GetListsResponse'));
  }

  /// Calls \[getLists\] and wraps the result in a \[BrevoOffsetPage\], so the following pages can be fetched with `nextPage()` or every item walked with `autoPaging()`.
  Future<BrevoOffsetPage<GetListsResponseListsItem>> getListsPaged(
      {int limit = 10,
      int offset = 0,
      GetListsRequestSort? sort,
      BrevoRequestOptions? options}) async {
    final page = await getLists(
        limit: limit, sort: sort, options: options, offset: offset);
    return BrevoOffsetPage<GetListsResponseListsItem>(
      items: page.lists,
      limit: limit,
      offset: offset,
      count: page.count,
      fetchPage: (next) => getListsPaged(
          limit: limit, sort: sort, options: options, offset: next),
    );
  }

  /// `GET /contacts/segments`
