  }

  /// Calls \[getSegments\] and wraps the result in a \[BrevoOffsetPage\], so the following pages can be fetched with `nextPage()` or every item walked with `autoPaging()`.
  Future<BrevoOffsetPage<GetSegmentsResponseSegmentsItem>> getSegmentsPaged(
