  /// `POST /contacts/batch`
  ///
  /// Update multiple contacts
  ///
  /// Update multiple contacts in a single API call by passing an array of contact objects. Each contact in the array must be identified by one of: email, id, or sms (only one identifier per contact). You can update attributes, blacklist status, list memberships, ext_id, and transactional email forbidden senders for each contact in the batch.
  Future<void> updateBatchContacts(UpdateBatchContactsRequest request,
      {BrevoRequestOptions? options}) async {
    await _client.requestVoid(
        method: 'POST',
        path: '/contacts/batch',
        body: request.toJson(),
        options: options);
  }

  /// `PUT /contacts/{identifier}`
  ///
  /// Update a contact
  ///
  /// &lt;Note&gt;Follow this format when passing a "SMS" phone number as an attribute.
  /// Accepted Number Formats 91xxxxxxxxxx +91xxxxxxxxxx 0091xxxxxxxxxx&lt;/Note&gt;
  /// There are 2 ways to update a contact &lt;br&gt;&lt;br&gt; Option 1- https://api.brevo.com/v3/contacts/{identifier} &lt;br&gt;&lt;br&gt; Option 2- https://api.brevo.com/v3/contacts/{identifier}?identifierType={} &lt;br&gt; &lt;br&gt; Option 1 only works if identifierType is email_id (for EMAIL) or contact_id (for ID of the contact),where you can directly pass the value of EMAIL and ID of the contact.   &lt;br&gt;&lt;br&gt; Option 2 works for all identifierType, use email_id for EMAIL attribute, contact_id for ID of the contact, ext_id for EXT_ID attribute, phone_id for SMS attribute, whatsapp_id for WHATSAPP attribute, landline_number_id for LANDLINE_NUMBER attribute
  ///
  /// \[identifier\]: Email (urlencoded) OR ID of the contact OR EXT_ID attribute (urlencoded) OR its SMS attribute value OR its WHATSAPP attribute value OR its LANDLINE_NUMBER attribute value
  ///
  /// \[identifierType\]: email_id for Email, contact_id for ID of the contact, ext_id for EXT_ID attribute, phone_id for SMS attribute, whatsapp_id for WHATSAPP attribute, landline_number_id for LANDLINE_NUMBER attribute
  Future<void> updateContact(UpdateContactRequest request,
      {required Object identifier,
      UpdateContactRequestIdentifierType? identifierType,
      BrevoRequestOptions? options}) async {
    await _client.requestVoid(
        method: 'PUT',
        path: '/contacts/${brevoPathSegment(identifier)}',
        query: <String, Object?>{'identifierType': identifierType?.value},
        body: request.toJson(),
        options: options);
  }

